local Text_AwakerTalent = readonly({
  AwakerTalent_117311_TalentDesc_1 = {
    Text = "· Mỗi khi Polux phát ra thẻ chỉ lệnh đầu tiên trong mỗi lượt, tăng sát thương của nó lên 200% sức tấn công của chính mình, tăng khiên lên 50% sức phòng thủ của chính mình, và khiến Polux nhận được 10 điểm điên loạn.\n· Sau khi kết thúc trận chiến, sát thương cơ bản và hiệu ứng sát thương \"Cứu rỗi khổ đau\" do Polux gây ra trong cuộc thám hiểm sẽ tăng 20%, hiệu ứng sát thương \"Cứu rỗi khổ đau\" trong trận chiến với boss sẽ gấp đôi."
  },
  AwakerTalent_117311_TalentName_1 = {
    Text = "Cứu rỗi bằng đau khổ"
  },
  AwakerTalent_120347_TalentDesc_1 = {
    Text = "·Khi Nhân Vật này có mặt trong đội, sẽ thay thế Cõi \"Hải Vực\" bằng Cõi \"Thâm Uyên: Hải Vực\".\n·Thương tổn xúc tu cơ bản được thay đổi thành 5% Sinh lực tối đa của đội.\n·Sau khi Bắt đầu khám phá, Khuếch đại sát thương của đội +50%, nếu đội chỉ gồm các Thể thức tỉnh Hải Vực hoặc Hỗn Mang, hiệu ứng Khuếch đại sát thương nhận được sẽ nhân đôi, nhưng khi bắt đầu chiến đấu sẽ không còn nhận thêm Xúc tu.\n·Không còn sở hữu hiệu ứng \"Râu chạm tập hợp\".\n·Tư thế râu chạm được thay đổi thành \"Thâm Uyên·Tư thế râu chạm\".\n·\"Thâm Uyên·Biển Lặng\": Nhận lá chắn bằng 25% Sinh lực tối đa, sau khi kết thúc lượt Xúc tu sẽ không còn tấn công, hồi chiêu 3 lượt.\n·\"Thâm Uyên·Sóng Gẩm\": Khiến thương tổn xúc tu trong lượt này trở thành 125%, sau khi gây Sát thương chủ động sẽ khiến 1 Xúc tu tấn công, nhưng sau khi kết thúc lượt sẽ mất 1 Xúc tu, hồi chiêu 3 lượt.\n·Sự thông thạo giới vực được thay đổi thành \"Thâm Uyên·Sự thạo biển sâu\", mỗi điểm Sự thông thạo giới vực làm tăng Lá chắn tăng cường của \"Thâm Uyên·Biển Lặng\" thêm 0.025% Sinh lực tối đa, và tăng thêm thương tổn xúc tu của \"Thâm Uyên·Sóng Gẩm\" thêm 0.025%.\n·Nếu đội chỉ gồm các Thể thức tỉnh Hải Vực hoặc Hỗn Mang, hiệu ứng \"Thâm Uyên·Sự thông thạo giới vực\" sẽ nhân đôi."
  },
  AwakerTalent_120347_TalentName_1 = {
    Text = "Đất tối vĩnh cửu"
  },
  AwakerTalent_122481_TalentDesc_1 = {
    Text = "·Tài năng này chỉ có hiệu lực trong cấp độ\"Bài sao\".\n·Thể thức tỉnh này có Thể chất, tấn công, phòng thủ tăng [Arg1] %, và sau khi thể thức tỉnh này chơi lần đầu tiên, nhận được [Arg2] điểm năng lượng chìa khóa bạc.\n·Mouchette gây sát thương cuối cùng tăng [Arg5]% cho kẻ thù\"Chủ trị\".\n·Tất cả thể thức tỉnh \"Đánh\" sát thương cơ bản tăng [Arg3]%.\n·Sau khi kích hoạt kháng cự tử vong, Mouchette nhận được [Arg4] điểm điên cuồng."
  },
