    Text = "·Tài năng này chỉ có hiệu lực trong màn chơi \"Chương Tinh Thần\".\n·Thể chất, tấn công, phòng thủ của Thể thức tỉnh này tăng [Arg1]%, và sau khi Thể thức tỉnh này lần đầu chơi Khai mở linh trí sẽ nhận được [Arg2] điểm Năng lượng chìa khóa bạc.\n·Tất cả Thể thức tỉnh kích hoạt hiệu ứng Ngộ độc tăng [Arg3]%.\n·Mỗi lớp \"Say mê\" làm giảm thêm 1% sát thương gây ra bởi kẻ địch \"Người\", khi bị xóa sẽ gây thêm 1% Sát Thương Thuần Túy dựa trên Sinh lực tối đa lên kẻ địch \"Người\"."
