  AwakerTalent_127223_TalentDesc_1 = {
    Text = "·Khi Arachne có trong đội, sẽ thay thế Cõi \"Siêu Chiều\" bằng Cõi \"Kỳ Điểm: Siêu Chiều\".\n·Xuyên Không Chiều Không Gian: Kích hoạt hiệu ứng này sau lần đầu tiên chơi thẻ lệnh trong mỗi vòng, đặt Bản gốc tạm thời của nó vào Khoảng không gian siêu việt và trao cho nó cùng bản sao tạm thời 25 lớp \"Ngọn hải đăng kỳ điểm\", Vòng Siêu Chiều không thể kích hoạt hiệu ứng này.\n·Ngọn hải đăng kỳ điểm: Mỗi lớp sở hữu tăng sát thương, lực lượng cố định và thương tổn xúc tu, Ngộ độc cố định, phản công cố định hiệu ứng cuối cùng thêm 2%, lá chắn cố định, hồi phục Sinh lực cố định, sức mạnh giảm xuống hiệu ứng cuối cùng tăng 1%, sau khi chơi sẽ bị xóa. Thẻ bài có Ngọn hải đăng kỳ điểm không thể kích hoạt \"Xuyên Không Chiều Không Gian\".\n·Khoảng không gian siêu việt: Khi Khoảng không gian siêu việt đạt giới hạn, cuối vòng thay vào đó sẽ kích hoạt Khoảng không gian siêu việt: không còn nhận vòng bổ sung, bỏ các Tay bài không được Giữ lại và kích hoạt hiệu ứng Hư vô, đặt tất cả thẻ bài trong Khoảng không gian siêu việt vào tay, đặt Điểm tính toán hiện tại thành 5 điểm. Sau khi kích hoạt Khoảng không gian siêu việt, vòng hiện tại được coi là Vòng Siêu Chiều.\n·\"Sự diệt vong Kỳ Điểm\": Lấy thẻ bài ngoài cùng bên trái của Khoảng không gian siêu việt. Hồi chiêu 3 vòng.\n·Sau khi bắt đầu khám phá, Khuếch đại sát thương của đội +50% và nhận 15 lớp \"Lăng Kính Kỳ Điểm\".\n·\"Lăng Kính Kỳ Điểm\": Tất cả thẻ lệnh được coi là có phần thưởng Ngọn hải đăng kỳ điểm tương đương.\n·Siêu việt tinh thông: Mỗi điểm Sự thông thạo giới vực của đội tăng số lớp \"Ngọn hải đăng kỳ điểm\" mà \"Lăng Kính Kỳ Điểm\" và \"Xuyên Không Chiều Không Gian\" áp dụng thêm 0.05%.\n·Siêu việt: Nếu đội chỉ gồm Thể thức tỉnh Siêu Chiều hoặc Hỗn Mang, hiệu ứng Siêu việt tinh thông và Khuếch đại sát thương mà Cõi cung cấp sẽ nhân đôi."
  },
  AwakerTalent_127223_TalentName_1 = {
    Text = "Sợi Chỉ Định Mệnh"
  },
  AwakerTalent_130395_TalentDesc_1 = {
    Text = "·Tài năng này chỉ có hiệu lực trong các màn chơi \"Chương sao\". \n·Thân thể được đánh thức này có thể tăng [Arg1]% về thể chất, sức tấn công và phòng thủ, đồng thời sau khi lần đầu tiên đạt được Thức tỉnh linh tri thức, sẽ nhận được [Arg2] điểm năng lượng chìa khóa bạc."
