  AwakerTalent_130398_TalentDesc_1 = {
    Text = "·Thiên phú này chỉ có hiệu lực trong các màn \"Bài Sao\".\n·Thể chất, tấn công, phòng thủ của Thức Tỉnh Thể này tăng [Arg1]%, và làm cho Thức Tỉnh Thể này nhận được [Arg2] điểm năng lượng Ngân Chìa Khóa sau lần đầu tiên đánh ra Linh Tri Giác Thức.\n·Thức Tỉnh Thể được \"Bài Hát Của Saya\" chọn nhận được [Arg3] tầng \"Cuồng Nhiệt Phồn Dục\", và làm cho lần Mật Lệnh tiếp theo có hiệu lực 2 lần.\n·\"Xâm Thực\" mà Saya gây ra lên kẻ địch \"Huyết Nhục\"được nâng cao thêm [Arg4]%."
  },
  AwakerTalent_130398_TalentDesc_10 = {
    Text = "·Thiên phú này chỉ có hiệu lực trong các màn \"Bài Sao\".\n·Thể chất, tấn công, phòng thủ của Thức Tỉnh Thể này tăng [Arg1]%, và làm cho Thức Tỉnh Thể này nhận được [Arg2] điểm năng lượng Ngân Chìa Khóa sau lần đầu tiên đánh ra Linh Tri Giác Thức.\n·Thức Tỉnh Thể được \"Bài Hát Của Saya\" chọn nhận được [Arg3] tầng \"Cuồng Nhiệt Phồn Dục\", và làm cho lần Mật Lệnh tiếp theo có hiệu lực 2 lần.\n·\"Xâm Thực\" mà Saya gây ra lên kẻ địch \"Huyết Nhục\"được nâng cao thêm [Arg4]%."
  },
