  AwakerTalent_130400_TalentDesc_1 = {
    Text = "·Tài năng này chỉ có hiệu lực trong màn chơi \"Thiên Thể Chương\".\n·Thể chất, tấn công, phòng thủ của Thể thức tỉnh này tăng [Arg1]%, và sau khi Thể thức tỉnh này lần đầu chơi Khai mở linh trí sẽ nhận được [Arg2] điểm Năng lượng chìa khóa bạc.\n·\"Vô Biên Hoang Ảnh\" gây hiệu ứng sức mạnh giảm xuống, bội số sức mạnh nhận được tăng [Arg3]%, mỗi lần có hiệu lực khiến lần \"Nhiễm Tội Thương Phong\" tiếp theo được hưởng thêm [Arg4]% cộng sức mạnh, giới hạn tối đa 1200%."
