  AwakerTalent_131854_TalentDesc_1 = {
    Text = "·Khi Saya có mặt trong đội, sẽ thay thế Cõi \"Huyết Nhục\" bằng Cõi \"Tận Sinh: Huyết Nhục\".\n·Dung hợp Phôi thai: Dung hợp Phôi thai nhận được mỗi lượt tăng lên 50~100, tăng theo Sinh lực đã mất, nhưng giới hạn Dung hợp Phôi thai tăng từ 100 lên 200, khi đạt giới hạn sẽ đặt \"Breeding embryos\" vào tay.\n·Breeding embryos: Khi chơi không còn nhận Tỉ lệ chí mạng, Nuốt chửng cũng không còn nhận lá chắn và Sức mạnh tạm thởi. Mỗi Thể thức tỉnh lần đầu tiêu thụ \"Breeding embryos\" trong mỗi lượt, nhận được 40 tầng \"Lễ hội phối giống\": Mỗi tầng tăng hiệu ứng cuối cùng của thương tổn Bùng nổ lần tiếp theo trong lượt này, lá chắn cố định, Sinh lực hồi phục cố định, lực lượng cố định, sức mạnh giảm xuống, thương tổn xúc tu tăng, Ngộ độc cố định, phản công cố định của Thể thức tỉnh đó lên 1％.\n·Lò nung đỏ thẫm: Lượng tích lũy tự động khi bắt đầu lượt thay đổi thành 10% Sinh lực đã mất, lượng tích lũy tối đa thay đổi thành 50% Sinh lực tối đa. Không còn tích lũy khi kết thúc chiến đấu, khi sử dụng có 3 lượt hồi chiêu.\n·Scarlet Erosion: Sau khi sử dụng Lò nung đỏ thẫm gây Xói mòn bằng 1% Sinh lực tối đa của mục tiêu cho tất cả kẻ thù, càng tiêu thụ nhiều Lò nung đỏ thẫm thì hiệu ứng Xói mòn càng mạnh, tối đa tăng 100%. Gây hiệu ứng Xói mòn gấp 5 lần đối với kẻ thù \"Vỏ rỗng\".\n·Sau khi bắt đầu khám phá, Sinh lực tối đa tăng 10％, Khuếch đại sát thương của đội +50%, mỗi khi bắt đầu lượt tất cả Thể thức tỉnh nhận được 20 tầng \"Lễ hội phối giống\". Nếu đội chỉ gồm các Thể thức tỉnh Huyết Nhục hoặc Hỗn Mang, Khuếch đại sát thương nhận được từ hiệu ứng này sẽ nhân đôi.\n·Sự thông thạo giới vực trở thành \"Sở Trưởng Thịt Máu\", mỗi điểm Sự thông thạo giới vực tăng \"Lễ hội phối giống\" nhận được từ \"Tận Sinh: Huyết Nhục\" lên 0.05%. \n·Nếu đội chỉ gồm các Thể thức tỉnh Huyết Nhục hoặc Hỗn Mang, hiệu ứng \"Sở Trưởng Thịt Máu\" sẽ nhân đôi."
  },
