  AwakerTalent_141303_TalentDesc_1 = {
    Text = "·Tài năng này chỉ có hiệu lực trong các Màn chơi \"Bài sao\".\n·Thể thức tỉnh này tăng [Arg1]% Thể chất, Tấn công và phòng thủ, đồng thời sau khi lần đầu tiên chơi Khai mở linh trí sẽ nhận được [Arg2] điểm Năng lượng chìa khóa bạc.\n·Sát thương cố định mà \"Pontos\" gây ra cho \"Hoan Lạc Gia Quyến\" tăng lên [Arg3]%.\n·\"Chuyến Săn Bất Tận\" cứ mỗi 10 điểm Điên loạn tiêu thụ sẽ nhận được thương tổn xúc tu bằng [Arg4]% Tấn công, \"Mộng Quỷ Càn Quét\" khi gây thương còn tạm thời giảm [Arg5]% Phòng thủ của mục tiêu thành Sức mạnh."
  },
