  AwakerTalent_145381_TalentDesc_1 = {
    Text = "·Tài năng này chỉ có hiệu lực trong Màn chơi \"Bài sao\".\n·Thể chất, Tấn Công, phòng thủ của Thể thức tỉnh này tăng [Arg1] %, và sau lần đầu tiên chơi Khai mở linh trí của Thể thức tỉnh này sẽ nhận được [Arg2] điểm Năng lượng chìa khóa bạc.\n·\"Ngư Thần Trảm Thế\" được hưởng thêm [Arg3]％ bonus Sức mạnh, sau khi Giết kẻ thù nhận được [Arg4] dấu đen, được hưởng bonus tỉ lệ rơi dấu ấn của bản thân, mỗi trận chiến tối đa có hiệu lực 1 lần."
