    Text = "·Khi Caraboo có mặt trong đội, sẽ thay thế Cõi \"Huyết Nhục\" bằng Cõi \"Tận Sinh: Huyết Nhục\".\n·Dung hợp Phôi thai: Dung hợp Phôi thai nhận được mỗi lượt tăng lên 50~100, tăng theo Sinh lực đã mất, nhưng giới hạn Dung hợp Phôi thai tăng từ 100 lên 200, khi đạt giới hạn sẽ đặt \"Breeding embryos\" vào tay.\n·Breeding embryos: Khi chơi không còn nhận Tỉ lệ chí mạng, Nuốt chửng cũng không còn nhận lá chắn và Sức mạnh tạm thởi. Mỗi Thể thức tỉnh lần đầu tiêu thụ \"Breeding embryos\" trong mỗi lượt, nhận được 40 tầng \"Lễ hội phối giống\": Mỗi tầng tăng hiệu ứng cuối cùng của thương tổn Bùng nổ lần tiếp theo trong lượt này, lá chắn cố định, Sinh lực hồi phục cố định, lực lượng cố định, sức mạnh giảm xuống, thương tổn xúc tu tăng, Ngộ độc cố định, phản công cố định của Thể thức tỉnh đó lên 1％.\n·Lò nung đỏ thẫm: Lượng tích lũy tự động khi bắt đầu lượt thay đổi thành 10% Sinh lực đã mất, lượng tích lũy tối đa thay đổi thành 50% Sinh lực tối đa. Không còn tích lũy khi kết thúc chiến đấu, khi sử dụng có 3 lượt hồi chiêu.\n·Scarlet Erosion: Sau khi sử dụng Lò nung đỏ thẫm gây Xói mòn bằng 1% Sinh lực tối đa của mục tiêu cho tất cả kẻ thù, càng tiêu thụ nhiều Lò nung đỏ thẫm thì hiệu ứng Xói mòn càng mạnh, tối đa tăng 100%. Gây hiệu ứng Xói mòn gấp 5 lần đối với kẻ thù \"Vỏ rỗng\".\n·Sau khi bắt đầu khám phá, Sinh lực tối đa tăng 10％, Khuếch đại sát thương của đội +50%, mỗi khi bắt đầu lượt tất cả Thể thức tỉnh nhận được 20 tầng \"Lễ hội phối giống\". Nếu đội chỉ gồm các Thể thức tỉnh Huyết Nhục hoặc Hỗn Mang, Khuếch đại sát thương nhận được từ hiệu ứng này sẽ nhân đôi.\n·Sự thông thạo giới vực trở thành \"Sở Trưởng Thịt Máu\", mỗi điểm Sự thông thạo giới vực tăng \"Lễ hội phối giống\" nhận được từ \"Tận Sinh: Huyết Nhục\" lên 0.05%. \n·Nếu đội chỉ gồm các Thể thức tỉnh Huyết Nhục hoặc Hỗn Mang, hiệu ứng \"Sở Trưởng Thịt Máu\" sẽ nhân đôi."
  },
  AwakerTalent_145718_TalentName_1 = {
    Text = "Tịnh Thổ Phồn Dục"
  },
  AwakerTalent_146937_TalentDesc_1 = {
    Text = "·Khi Lotan: Ngư Thần có trong đội, thay thế Cõi \"Hỗn Mang\" bằng Cõi \"Khởi Nguyên: Hỗn Mang\".\n·Dòng Chảy Khởi Nguyên: Năng lượng chìa khóa bạc cơ bản tăng lên 2000 điểm, Khuếch đại sát thương của đội +50%, tấn công và phòng thủ của tất cả Thể thức tỉnh tăng 10%. Nếu đội chỉ gồm thân thể hỗn độn, hiệu ứng Khuếch đại sát thương nhận được sẽ nhân đôi. Khi chiến đấu bắt đầu, nhận được 2000 điểm Năng lượng chìa khóa bạc.\n·Chìa Khóa Hội Tụ: Cấp độ nạp năng lượng chìa khóa bạc của tất cả Thể thức tỉnh trở thành giá trị trung bình của đội. Không còn nhận Năng lượng chìa khóa bạc dựa trên Giá trị Điểm tính toán, mà thay vào đó mỗi Thể thức tỉnh nhận được Năng lượng chìa khóa bạc bằng \"Sạc năng lượng chìa khóa bạc của Thể thức tỉnh đó × 3 + 100\" từ thẻ lệnh đầu tiên mỗi vòng.\n·Cõi Bất Phân: Không còn kích hoạt hiệu ứng Siêu việt, nhân đôi tinh thông, nhân đôi Khuếch đại của các Cõi khác.\n·Vọng Âm Khởi Nguyên: Khai mở linh trí nhận được Chuẩn bị 1, lần đầu tiên chơi trong mỗi vòng sẽ tự động kích hoạt Mật lệnh đang mang.\n·Ký Ức Mảnh Vỡ: Mật lệnh được thay thế bằng \"Khởi Nguyên · Song Điều\" và \"Khởi Nguyên · Tam Lệnh\", Mật lệnh tự mang theo không thể kích hoạt.\n·Khởi Nguyên · Song Điều: phát hiện 3 loại Mật lệnh từ các Mật lệnh đang Trong Tay, chọn 1 Mật lệnh để kích hoạt 2 lần.\n·Khởi Nguyên · Tam Lệnh: phát hiện 3 nhóm Mật lệnh từ các Mật lệnh đang Trong Tay, mỗi nhóm gồm 3 loại Mật lệnh khác nhau, chọn một nhóm để các Mật lệnh trong đó lần lượt kích hoạt 1 lần.\n·Mật lệnh trong Khởi Nguyên · Song Điều và Khởi Nguyên · Tam Lệnh sẽ bao gồm tám loại \"Ký Ức Khởi nguyên\".\n·Khởi Nguyên · Song Điều và Khởi Nguyên · Tam Lệnh chỉ được tính là kích hoạt 1 lần Mật lệnh, khi kích hoạt nhiều lần chỉ có hiệu lực với Mật lệnh đầu tiên được kích hoạt.\n·Sự thông thạo giới vực trở thành \"Khởi Nguyên · Hỗn Mang Tinh Thông\", mỗi điểm Sự thông thạo giới vực tăng cường độ Mật lệnh thêm 0.05%.\n·Mỗi điểm cường độ Mật lệnh tăng Ngộ độc cố định, phản công cố định, lực lượng cố định, thương tổn xúc tu cố định, Tàn tro cũ cố định 2%, tăng lá chắn cố định, hồi phục Sinh lực cố định, sức mạnh giảm xuống, Tỉ lệ chí mạng, Sát thương chí mạng, Khuếch đại sát thương, Sự thông thạo giới vực, điên cuồng, Dung hợp Phôi thai, Năng lượng chìa khóa bạc 1%.\n·Nếu đội chỉ gồm thân thể hỗn độn, hiệu ứng \"Khởi Nguyên · Hỗn Mang Tinh Thông\" sẽ nhân đôi."
  },
