  AwakerTalent_44845_TalentDesc_1 = {
    Text = "· Mỗi khi Lily, bánh xe định mệnh và giao ước cung cấp 1% kháng cự cái chết, \"Đầm cấm\" và \"Phòng thủ cơ bản\" sẽ tăng 0.25% khả năng che chắn cơ bản, và mức tích lũy và giới hạn của chịu đựng tăng 0.25% trong trận chiến lãnh đạo.\n· Khi Lily trong đội, khi mất 1 điểm cuộc sống sẽ nhận được 1 lớp chịu đựng, giới hạn tầng của chịu đựng tương đương với máu tối đa."
  },
