  AwakerTalent_46445_TalentDesc_1 = {
    Text = "·Lò Salvador cung cấp hưởng hiệu quả hồi phục Cuộc sống hồi phục tăng thêm."
  },
  AwakerTalent_46445_TalentName_1 = {
    Text = "linh hồn mục tử"
  },
  AwakerTalent_46446_TalentDesc_1 = {
    Text = "· Ramona nhận thêm 2.5 điểm thuộc tính sạc lại chìa khóa bạc. Mỗi cấp độ sự tương hợp sẽ thêm cho Ramona 0.5 điểm thuộc tính sạc lại chìa khóa bạc.\n· Mỗi điểm cấp độ sạc lại chìa khóa bạc sẽ làm cho \"Kiếm Nữ Hoàng\" tăng 1% sát thương cơ bản, sau khi chơi sẽ nhận được 0.75 thông thạo cõi tạm thời."
  },
  AwakerTalent_46446_TalentName_1 = {
    Text = "Cộng hưởng của Trái tim và Bạc"
  },
  AwakerTalent_46487_TalentDesc_1 = {
    Text = "· Vòng lặp Ramona nhận thêm 2.5 điểm thuộc tính sạc lại chìa khóa bạc. Mỗi cấp độ sự tương hợp sẽ thêm cho Vòng lặp Ramona 0.5 điểm thuộc tính sạc lại chìa khóa bạc.\n· Mỗi điểm cấp độ sạc lại chìa khóa bạc sẽ làm cho \"Đánh cơ bản\" của vòng lặp thêm 0.2% tỷ lệ chí mạng, và hiệu ứng hồi hoàn của \"Phòng thủ cơ bản\" tăng 0.2 điểm Aliemus."
  },
  AwakerTalent_46487_TalentName_1 = {
    Text = "Cộng hưởng của Trái tim và Bạc"
  },
  AwakerTalent_49872_TalentDesc_1 = {
    Text = "·Nautila mỗi có 1 điểm thuộc tính Cõi thông thạo, tăng 0.25% phản kích từ \"Sẵn sàng và thiết lập\"."
  },
  AwakerTalent_49872_TalentName_1 = {Text = "bảo trì"},
  AwakerTalent_49873_TalentDesc_1 = {
    Text = "· Mỗi khi Nymphaea có 1% thuộc tính tăng cường sát thương, hiệu ứng cơ bản \"Tiếng chuông viếc\" và \"Đám tang của chính mình\" gây ra sẽ tăng 0.5%."
  },
  AwakerTalent_49873_TalentName_1 = {
    Text = "Nhiễm nhiễm"
  },
  AwakerTalent_51744_TalentDesc_1 = {
    Text = "·Khi trận chiến bắt đầu, đặt 1 lá \"Điên rồ\" vào tay. \n·\"Đánh cơ bản\" của Miriam được hưởng 100% tăng thương tổn xúc tu. \n·Mỗi khi thể thức tỉnh, vòng mệnh và giao ước của Miriam cung cấp 1% sát thương chí mạng, sẽ làm tăng 0.2% sức mạnh bùng nổ, thương tổn xúc tu, điên cuồng, hiệu ứng ngộ độc và kích hoạt ngộ độc."
  },
  AwakerTalent_51744_TalentName_1 = {
    Text = "Sự Trung Thành Bất Diệt"
  },
  AwakerTalent_52071_TalentDesc_1 = {
    Text = "· Tulu bản thân, bánh xe định mệnh trang bị và giao ước mỗi cung cấp 1 điểm cấp độ hồi phục điên loạn,\"Đòn tấn công cơ bản\" chịu 5% thiệt hại xúc tu và sức mạnh cộng thêm,\"Lệnh hạ thấp\" chịu 15% thiệt hại xúc tu và sức mạnh cộng thêm."
  },
  AwakerTalent_52071_TalentName_1 = {
    Text = "Quyền năng Thần Vương"
  },
  AwakerTalent_52086_TalentDesc_1 = {
    Text = "· Mỗi khi Sanga, bánh xe định mệnh và giao ước cung cấp 1% kháng cự cái chết, \"Đánh cơ bản\" và \"Phòng thủ cơ bản\" sẽ nhận được 0.03 điểm Aliemus, và \"Nghệ thuật đã mất\" sẽ nhận thêm 0.15% tỷ lệ chí mạng và sát thương chí mạng."
  },
  AwakerTalent_52086_TalentName_1 = {
    Text = "Cảm hứng từ cái chết"
  },
  AwakerTalent_54047_TalentDesc_1 = {
    Text = "· Mỗi điểm hồi phục Aliemus mà Búp bê cung cấp, \"Phẫu thuật bên ngoài\" và \"Có qua có lại\" sẽ tăng 0.5% hiệu ứng hồi hồi cuộc sống."
  },
  AwakerTalent_54047_TalentName_1 = {
    Text = "Giải cấu trúc linh tri"
  },
  AwakerTalent_54072_TalentDesc_1 = {
    Text = "· Mỗi khi Ogier có 1% thuộc tính rơi ấn ký đen, \"Bảy nghệ thuật và đức hạnh\" sẽ tăng 3% sức mạnh tạm thời."
  },
  AwakerTalent_54072_TalentName_1 = {
    Text = "Luyện hóa vô hình"
  },
  AwakerTalent_54073_TalentDesc_1 = {
    Text = "·Mỗi khi Alva có 1% thuộc tính kháng cự cái chết, sát thương cơ bản gây ra sẽ tăng 0.5%."
  },
  AwakerTalent_54073_TalentName_1 = {
    Text = "trường nhìn động"
  },
