  AwakerTalent_54158_TalentDesc_1 = {
    Text = "Với mỗi 1% tỷ lệ chí mạng Sorel có, \"Thủ\" cơ bản\" sẽ nhận thêm 0.2 Aliemus."
  },
  AwakerTalent_54158_TalentName_1 = {
    Text = "Giữ Gìn Khí Sắc"
  },
  AwakerTalent_55109_TalentDesc_1 = {
    Text = "·Jenkin Người đánh thức bản thân, Bánh xe định mệnh, và Giao ước mỗi cung cấp 1% Tỷ lệ chí mạng, sẽ làm tăng 2% sát thương cơ bản cho \"Đánh cơ bản\" và \"Brown's Action\"."
  },
  AwakerTalent_55109_TalentName_1 = {
    Text = "Đồng lòng chống địch"
  },
  AwakerTalent_55176_TalentDesc_1 = {
    Text = "· Mỗi điểm thuộc tính sạc lại chìa khóa bạc mà người đánh thức Erica, bánh xe định mệnh và giao ước cung cấp, sẽ làm cho Erica nhận được 0.5% tỷ lệ chí mạng tạm thời và sát thương chí mạng."
  },
  AwakerTalent_55176_TalentName_1 = {
    Text = "Nguồn năng lượng ngoại vi"
  },
  AwakerTalent_55202_TalentDesc_1 = {
    Text = "· Bắt đầu lượt, nhận được 1 lớp Mộng dẫn.\n· Mỗi khi tiêu thụ 1 lớp Mộng dẫn, tăng 5% sức mạnh phản kích của \"Người bảo vệ lạc lối\" và \"Thành phố mơ chết\" trong trận chiến.\n· Mỗi khi người đánh thức Wanda, bánh xe định mệnh và giao ước cung cấp 1% thuộc tính tăng cường sát thương, phản kích của \"Thành phố mơ chết\" sẽ tăng thêm 0.75%."
  },
  AwakerTalent_55202_TalentName_1 = {
    Text = "Khải thị"
  },
  AwakerTalent_55367_TalentDesc_1 = {
    Text = "· Mỗi điểm thông thạo cõi mà người đánh thức Casiah, bánh xe định mệnh và giao ước cung cấp, \"Lễ hội ma thuật\" sẽ tăng sát thương cơ bản của Casiah lên 0.2%."
  },
  AwakerTalent_55367_TalentName_1 = {
    Text = "Maestro Ma thuật"
  },
  AwakerTalent_55507_TalentDesc_1 = {
    Text = "· Mỗi khi người đánh thức Tincture, bánh xe định mệnh và giao ước cung cấp 1% thuộc tính rơi ấn ký đen, \"Cực quang\" sẽ nhận được thêm 0.15% tỷ lệ chí mạng tạm thời."
  },
  AwakerTalent_55507_TalentName_1 = {
    Text = "Du lịch hành tinh"
  },
  AwakerTalent_55837_TalentDesc_1 = {
    Text = "\"Đánh\" cơ bản và \"Thủ\" cơ bản của Horla cũng được coi như một bài thơ. Mỗi khi bài thơ kích hoạt hiệu ứng \"Nhảy Vọt\", Horla sẽ thay đổi sang trạng thái cảm xúc khác, cảm xúc này sẽ ảnh hưởng trực tiếp đến hiệu quả của bài thơ. Ở các trạng thái cảm xúc khác nhau sẽ mang lại hiệu quả liên tục khác nhau cho đội nhóm.\n· Với mỗi 1% Kháng Tử của Horla, hiệu ứng này sẽ tăng thêm 0.1% giá trị hiệu quả."
  },
  AwakerTalent_55837_TalentName_1 = {
    Text = "Ngòi Bút Trữ Tình"
  },
  AwakerTalent_56174_TalentDesc_1 = {
    Text = "·Với mỗi 1% thuộc tính Sát thương mạnh mà Faros sở hữu, Khiên được tạo bởi \"Thành phố mất tích\" sẽ tăng thêm 0,4%."
  },
  AwakerTalent_56174_TalentName_1 = {
    Text = "Sự say mê trở về quê hương"
  },
  AwakerTalent_56175_TalentDesc_1 = {
    Text = "· Mỗi khi Caecus có 1% thuộc tính rơi ấn ký đen, \"Đánh cơ bản\" sẽ nhận được 1% cộng thêm phản kích."
  },
  AwakerTalent_56175_TalentName_1 = {
    Text = "Gai phản nghịch"
  },
  AwakerTalent_56223_TalentDesc_1 = {
    Text = "· Sau khi Celeste chơi thẻ lệnh, kích hoạt 1 xúc tu tấn công kẻ thù, mỗi 1 điểm thông thạo cõi từ bản thân Celeste, mệnh luân, mật khế sẽ khiến lần kích hoạt này gây thêm 0.5% sát thương xúc tu."
  },
  AwakerTalent_56223_TalentName_1 = {
    Text = "Sừng Viễn Hành"
  },
  AwakerTalent_57336_TalentDesc_1 = {
    Text = "·Mỗi khi Salvador có thêm 1% thuộc tính rơi Ấn ký đen, giới hạn Lò nung đỏ thẫm tăng thêm 0.15% Máu tối đa."
  },
  AwakerTalent_57336_TalentName_1 = {
    Text = "điểm khởi đầu"
  },
  AwakerTalent_57408_TalentDesc_1 = {
    Text = "·Agrippa bản thân, Bánh xe định mệnh và Giao ước trang bị, mỗi 1% tăng thuộc tính rơi Ấn ký đen, làm tăng 0.5% Khiên cơ bản của \"Bảo vệ nhợt nhạt\" và tăng 1% độc dược cơ bản."
  },
  AwakerTalent_57408_TalentName_1 = {
    Text = "Biểu tượng Hợp đồng"
  },
  AwakerTalent_57419_TalentDesc_1 = {
    Text = "· Mỗi khi Phiệt có 1% thuộc tính kháng cự tử vong, phản công của \"Berço của các ngôi sao\" và \"sao không giới hạn\" sẽ tăng 0.2%, và giới hạn kháng cự tử vong của \"Berço của các ngôi sao\" tăng thêm 2%."
  },
  AwakerTalent_57419_TalentName_1 = {
    Text = "Cradle thứ cấp"
  },
  AwakerTalent_57567_TalentDesc_1 = {
    Text = "· Mỗi khi Helot có 1% thuộc tính tăng cường sát thương, \"Bế tắc sống còn\" sẽ tăng 0.3% sát thương gây ra của Helot trong lượt này."
  },
  AwakerTalent_57567_TalentName_1 = {
    Text = "Dấu vết đau đớn"
  },
  AwakerTalent_58448_TalentDesc_1 = {
    Text = "·Lắc giết kẻ thù sẽ nhận được 5 dấu đen, mỗi 1% dấu đen rơi ra từ Lắc sẽ làm tăng lượng nhận được lên 1%, mỗi cuộc khám phá tối đa có hiệu lực 5 lần.\n·Thông qua chiến đấu để nhận 50/125/250 dấu đen, giới hạn sáng tạo +1, vào cuối trận chiến chọn một <C05_zaowu:「Di sản của Hỗn loạn」> để thêm vào danh sách di vật."
  },
  AwakerTalent_58448_TalentName_1 = {
    Text = "Người thắng ăn hết"
  },
  AwakerTalent_70306_TalentDesc_1 = {
    Text = "· Trong trận chiến lãnh đạo, bắt đầu lượt và sau khi \"Dung hợp búp bê\" phát nổ Aliemus, nhận được 1 lớp \"Tận thế\". \"Tận thế\" tối đa có 10 lớp, khi đạt đến 10 lớp, thêm 1 thẻ \"Kết thúc Ảo giác\" vào tay."
  },
  AwakerTalent_70306_TalentName_1 = {
    Text = "Đường diệt vong"
  },
  AwakerTalent_74099_TalentDesc_1 = {
    Text = "·Tài năng này chỉ có hiệu lực trong cấp độ \"Bài sao\". \n·Thể chất, tấn công và phòng thủ của thể thức tỉnh này tăng [Arg1] %, và sau khi thể thức tỉnh này lần đầu tiên chơi khai mở linh trí, nhận được [Arg2] điểm năng lượng chìa khóa bạc. \n·Mỗi râu chạm tấn công sẽ làm tăng thiệt hại tạm thời của xúc tu lên [Arg3]% sức tấn công của tulô, mỗi lượt tối đa có hiệu lực [Arg4] lần.\n·Khi trong đội có 1/2/3 thể thức tỉnh \"Lemuria\" khác, thiệt hại xúc tu mà tất cả kẻ địch nhận được tăng 10%/25%/50%."
  },
