  AwakerTalent_74105_TalentDesc_1 = {
    Text = "·Tài năng này chỉ có hiệu lực trong cấp độ \"Bài sao\". \n·Thể chất, tấn công và phòng thủ của thể thức tỉnh này tăng [Arg1] %, và sau khi thể thức tỉnh này chơi thẻ Khai mở linh trí lần đầu tiên, nhận được [Arg2] điểm năng lượng chìa khóa bạc. \n·Mỗi khi tiêu thụ 1 lá \"Phân chia tuyến\" trong \"Biển ồn ào\", sát thương mà Ô Ryta gây ra trong trận chiến này sẽ tăng [Arg3]% tấn công. Trong trận chiến Lãnh đạo, nếu \"Biển ồn ào\"đã tiêu thụ ít nhất 20 lá \"Phân chia tuyến\", số lần gây sát thương khi chơi và tiêu thụ thẻ \"Phân chia tuyến\" tăng thêm 1. Mỗi lượt, [Arg4] lá \"Phân chia tuyến\"đầu tiên được chơi sẽ không thêm \"Điều hòa sức mạnh tính toán\"."
  },
