  AwakerTalent_74110_TalentDesc_1 = {
    Text = "·Tài năng này chỉ có hiệu lực trong cấp độ\"Bài sao\".\n·Thể chất, tấn công, phòng thủ của thể thức tỉnh này tăng [Arg1] %, và sau khi thể thức tỉnh này chơi khai mở linh trí lần đầu tiên, nhận được [Arg2] điểm năng lượng chìa khóa bạc.\n·Sau khi chơi \"Linh cảm\", nhận được lực lượng tạm thời bằng [Arg3]% tấn công, và kích hoạt 1 lần \"Tích thế nhạc âm\", mỗi lượt có hiệu lực tối đa 5 lần."
  },
