    Text = "·Tài năng này chỉ có hiệu lực trong màn \"Bài sao\".\n·Thể chất, tấn công và phòng thủ của thể thức tỉnh này tăng [Arg1] %, và sau khi thể thức tỉnh này lần đầu tiên chơi khai mở linh trí, sẽ nhận được [Arg2] điểm năng lượng chìa khóa bạc.\n·Khi bắt đầu chiến đấu, nếu tồn tại kẻ địch \"Dã thú\", lực lượng gây ra của Cassia trong trận chiến này tăng [Arg3]%. Sau khi \"Biến mất hết\"được sử dụng lần đầu mỗi lượt, kích hoạt hiệu ứng dư ba của lá bài được xáo vào bộ bài rút."
  },
