  AwakerTalent_74113_TalentDesc_1 = {
    Text = "·Tài năng này chỉ có hiệu lực trong màn chơi \"Thiên Thể Chương\".\n·Thể chất, tấn công, phòng thủ của Thể thức tỉnh này tăng [Arg1]%, và sau khi Thể thức tỉnh này lần đầu chơi Khai mở linh trí sẽ nhận được [Arg2] điểm Năng lượng chìa khóa bạc.\n·\"Đòn roi của Sự điên cuồng được kiềm chế\" nhận được Giữ lại và Chuẩn bị. Kẻ địch có ý định gây sát thương sẽ chịu Sát thương chủ động của Pandia tăng [Arg3]%, mục tiêu mỗi lần tấn công thêm 1 lần tăng thêm 5%, tối đa tăng thêm 20%."
