  AwakerTalent_74115_TalentDesc_1 = {
    Text = "·Tài năng này chỉ có hiệu lực trong các màn chơi \"Bài sao\". \n·Thân thể được đánh thức này có thể chất, tấn công, phòng thủ tăng [Arg1] %, và sau khi đánh ra lần đầu tiên Thức tỉnh linh tri, thân thể được đánh thức này sẽ nhận được [Arg2] điểm năng lượng chìa khóa bạc. \n·Trong mỗi lượt, [Arg3] lá \"Tiếng thét, máu\"đầu tiên được đánh ra sẽ không thêm \"Điều hòa sức tính toán\". Sát thương cơ bản do Yu U Hahi gây ra tăng [Arg4]%, khi sức sống dưới 25%, hiệu ứng tăng gấp đôi."
  },
