  AwakerTalent_74124_TalentDesc_1 = {
    Text = "· Tài năng này chỉ có hiệu lực trong cấp độ 「Ngôi sao」.\n· Sức khỏe, tấn công và phòng thủ của người đánh thức này tăng [Arg1] %, và khi người đánh thức này lần đầu tiên gây ra hiệu ứng đánh thức tri thức sẽ nhận được [Arg2] điểm năng lượng chìa khóa bạc.\n· Sát thương từ búp bê gây ra cơn điên và hiệu ứng chữa lành từ cơn điên bùng nổ tăng [Arg3]%, mỗi 1 người khác trong đội là người đánh thức cõi hỗn loạn sẽ tăng thêm [Arg4]%."
