  AwakerTalent_74126_TalentDesc_1 = {
    Text = "·Tài năng này chỉ có hiệu lực trong cấp độ\"Bài sao\".\n·Thể chất, tấn công, phòng thủ của thể thức tỉnh này tăng [Arg1] %, và sau khi thể thức tỉnh này lần đầu tiên chơi khai mở linh trí, sẽ nhận được [Arg2] điểm năng lượng chìa khóa bạc.\n·Hiệu quả nhận lực lượng của Lôi Á tăng [Arg4]%, sau khi chơi \"thẻ lệnh\" của Lôi Á, nhận được [Arg3]% lực lượng dựa trên tấn công của Lôi Á, hiệu quả này tăng tối đa 200% theo sinh mệnh đã mất hiện tại, mỗi lượt có hiệu lực tối đa 3 lần."
