  AwakerTalent_74129_TalentDesc_1 = {
    Text = "·Tài năng này chỉ có hiệu lực trong cấp độ\"Bài sao\".\n·Thể chất, tấn công, phòng thủ của thể thức tỉnh này tăng [Arg1] %, và sau khi thể thức tỉnh này chơi linh trí thức tỉnh lần đầu, sẽ nhận được [Arg2] điểm năng lượng chìa khóa bạc.\n·Sát thương cuối cùng của \"Đả kích\" của Lili tăng [Arg3]%, lượng tăng gấp đôi trong trận thủ lĩnh. Sau khi nhận tấn công từ kẻ địch \"Siêu chiều\", nhận hiệu quả hồi phục trì hoãn bằng [Arg4]% sinh mệnh mất do đợt tấn công này. Hiệu quả tăng sát thương theo \"Nhẫn nại\" của \"Đả kích báo thường\"được hưởng [Arg5]% gia tăng sát thương mạnh."
