  AwakerTalent_74132_TalentDesc_1 = {
    Text = "·Tài năng này chỉ có hiệu lực trong cấp độ \"Bài sao\".\n·Thể chất, tấn công và phòng thủ của thể thức tỉnh này tăng [Arg1] %, và thể thức tỉnh này sẽ nhận được [Arg2] điểm năng lượng chìa khóa bạc sau khi chơi khai mở linh trí lần đầu.\n·Ngộ độc do Pháp Luân Tư gây ra tăng [Arg3]%. Vào cuối lượt của \"thành phố cổ xưa bị mất\", ra lệnh cho tất cả xúc tu tấn công 1 lần, nhưng những đòn tấn công này chỉ gây [Arg4]% sát thương.\n·Khi trong đội có 1/2/3 thể thức tỉnh \"Limoria\" khác, sát thương cường hóa +20%/50%/100%."
