    Text = "·Tài năng này chỉ có hiệu lực trong cấp độ \"Chương sao\".\n·Thể chất, tấn công và phòng thủ của người đánh thức này tăng [Arg1] %, đồng thời khiến người đánh thức này nhận được [Arg2] điểm năng lượng chìa khóa bạc sau khi đánh thức lần đầu tiên.\n·Năng lượng sạc lại chìa khóa bạc của Ramona tăng [Arg3] %, nhận được năng lượng chìa khóa bạc [Arg4] % khi bắt đầu trận chiến."
