  AwakerTalent_74135_TalentDesc_1 = {
    Text = "·Tài năng này chỉ có hiệu lực trong cấp độ\"Bài sao\".\n·Thể chất, tấn công, phòng thủ của thể thức tỉnh này tăng [Arg1] %, và sau khi thể thức tỉnh này chơi lần đầu tiên khai mở linh trí sẽ nhận được [Arg2] điểm năng lượng chìa khóa bạc.\n·Khi trận thủ lĩnh bắt đầu, nhận được kháng tử vong tương đương [Arg3]% thuộc tính kháng tử vong của Orla. Mỗi lần kích hoạt kháng tử vong, hiệu quả tương ứng của \"Phân Hoa Thiên Chương\" tăng [Arg4]% cho đến khi lượt kết thúc."
  },
