  AwakerTalent_74136_TalentDesc_1 = {
    Text = "·Tài năng này chỉ có hiệu lực trong các màn chơi \"Chương sao trời\". \n·Thể chất, tấn công và phòng thủ tăng [Arg1]%, và khi thân thể được đánh thức này lần đầu tiên đạt được Thức tỉnh linh tri thức, nó sẽ nhận được [Arg2] điểm năng lượng chìa khóa bạc. \n·Khi chiến đấu bắt đầu, đặt 1 lá \"Lửa xanh bị phân rã\" có \"Tiêu thụ\" vào tay, và làm cho sát thương cơ bản của \"Lửa xanh\" cùng các thẻ liên quan tăng [Arg3]%."
