  AwakerTalent_74137_TalentDesc_1 = {
    Text = "·Tài năng này chỉ có hiệu lực trong cấp độ「Bài sao」.\n·Thể chất, tấn công và phòng thủ của thể thức tỉnh này tăng [Arg1] %, và sau khi thể thức tỉnh này lần đầu chơi thẻ khai mở linh trí sẽ nhận được [Arg2] điểm năng lượng chìa khóa bạc.\n·Khi di tích tro tàn làm mới, xác suất xuất hiện giảm giá tăng [Arg3]%, và tỷ lệ giảm giá tăng [Arg4]%.\n·Sát thương cơ bản của「Đòn chí mạng đứt cổ」tăng [Arg5] %, tính toán độc lập với sát thương cơ bản tăng từ hạ gục."
  },
