  AwakerTalent_78618_TalentDesc_1 = {
    Text = "·Tài năng này chỉ có hiệu lực trong màn chơi \"Bài sao\".\n·Thể chất, tấn công, phòng thủ của thể thức tỉnh này tăng [Arg1] %, và sau khi thể thức tỉnh này lần đầu tiên chơi khai mở linh trí, sẽ nhận được [Arg2] điểm năng lượng chìa khóa bạc.\n·Hiệu ứng sát thương cơ bản do \"Cứu Chuộc Khổ Đau\" gây ra tăng thêm [Arg3]% tấn công lực của Pollux.\n·Mỗi khi cộng dồn 50 tầng \"Tội Ấn\" sẽ đưa 1 lá\"Thánh Tâm\" vào tay.\n· Sau khi \"Tội Ấn\"đạt 100 tầng,\"Thánh Tâm\" sau khi bị tiêu hao do chơi lần thứ 3 sẽ rút 1 lá\"Thẻ kỹ năng\" của bản thân.\n·Khi gây sát thương, hiệu ứng của \"Tội Ấn\"đối với kẻ địch \"Giáo Hội Đề Đăng\"được nhân đôi."
  },
