  AwakerTalent_78620_TalentDesc_1 = {
    Text = "·Tài năng này chỉ có hiệu lực trong màn chơi \"Thiên Thể Chương\".\n·Thể chất, tấn công, phòng thủ của Thể thức tỉnh này tăng [Arg1]%, và sau khi Thể thức tỉnh này lần đầu chơi Khai mở linh trí sẽ nhận được [Arg2] điểm Năng lượng chìa khóa bạc.\n·Khi chiến đấu bắt đầu, khiến Thương tổn xúc tu nhận được của tất cả kẻ địch tăng [Arg3]%, hiệu ứng nhân đôi với kẻ địch \"Hải Vực\". Sát thương chủ động của \"Hình phạt Sấm sét\" gây ra cho kẻ địch \"Hải Vực\" tăng [Arg4]%."
  },
