    Text = "·Tài năng này chỉ có hiệu lực trong giai đoạn \"Bài sao\".\n·Thể chất, tấn công và phòng thủ của thể thức tỉnh này tăng [Arg1] %, và sau khi thể thức tỉnh này chơi lần đầu tiên khai mở linh trí, sẽ nhận được [Arg2] điểm năng lượng chìa khóa bạc.\n·Hiệu ứng tăng ích của \"Hoạt Diễm\" tăng [Arg3]%, sau khi bắt đầu lượt và trước giai đoạn bỏ bài, xóa \"Thiêu Đốt\" của tất cả bài trên tay, mỗi tầng khiến Katy Gula nhận được 1 tầng \"Bạo Viêm\"."
