    Text = "·Tài năng này chỉ có hiệu lực trong cấp độ \"Bài sao\". \n·Thể chất, tấn công, phòng thủ của thể thức tỉnh này tăng [Arg1] %, và sau khi thể thức tỉnh này lần đầu tiên chơi Khai mở linh trí sẽ nhận được [Arg2] điểm năng lượng chìa khóa bạc.\n·\"Mệnh vận tài đoán\" do Arachne gây ra tăng [Arg3]%, \"Mệnh vận tài đoán\" gây ra đối với kẻ địch dị biến thể được nhân đôi."
