  AwakerTalent_78645_TalentDesc_1 = {
    Text = "·Tài năng này chỉ có hiệu lực trong màn \"Bài sao\".\n·Thể chất, tấn công và phòng thủ của thể thức tỉnh này tăng [Arg1]%, và sau khi thể thức tỉnh này lần đầu tiên chơi khai mở linh trí, sẽ nhận được [Arg2] điểm năng lượng chìa khóa bạc.\n·Sức mạnh nhận được của tất cả thể thức tỉnh tăng [Arg3]%.\n·Khi Clementine gây thương cho kẻ địch \"Insectoid\", sẽ áp dụng hiệu ứng chảy máu [Arg4]% sát thương lên mục tiêu. Khi Clementine lần đầu tiên gây lá chắn hoặc hồi phục sinh lực mỗi lượt, sẽ làm cho kẻ địch \"Insectoid\" tạm thời mất [Arg5]% sức mạnh phòng thủ."
  },
