    Text = "·Tài năng này chỉ có hiệu lực trong cấp độ\"Bài sao\".\n·Thể chất, tấn công và phòng thủ của thể thức tỉnh này tăng [Arg1] %, và sau khi thể thức tỉnh này lần đầu tiên chơi khai mở linh trí, nhận được [Arg2] điểm năng lượng chìa khóa bạc.\n·Sát thương do Đản Vọng·Murphy gây ra cộng thêm [Arg3]%\"Hiến Tế\", hiệu ứng tăng cường của \"Mệnh Khế\"đối với \"Nghi Thức Giáng Sinh\"được nhân đôi.\n·Khi trong đội có 1/2/3 thể thức tỉnh \"Limoria\" khác, giới hạn sinh mệnh tăng 6%/15%/30%. Thể thức tỉnh \"Limoria\" sau khi giải phóng cuồng khí bùng phát sẽ nhận được khiên bằng 50%/125%/250% phòng thủ lực của Đản Vọng·Murphy, hiệu ứng này mỗi lượt có hiệu lực tối đa 1 lần và không chịu ảnh hưởng của hiệu ứng tăng khiên."
  },
