  AwakerTalent_79211_TalentDesc_1 = {
    Text = "·Thẻ lệnh của Clementine gây sát thương sau đó nhận 1 tầng \"Cảm giác cộng hưởng\".\n·Thức tỉnh thể của Clementine, bánh xe định mệnh, mỗi giao ước cung cấp một điểm thuộc tính Sạc lại chìa khóa bạc, tỷ lệ chí mạng và sát thương chí mạng tăng 0,35%.\n·Sau khi bắt đầu vòng Ultra, loại bỏ tất cả \"Vết thương linh hồn\" và \"Sợ hãi cố định\" trên mọi địch. Mỗi lần loại bỏ một tầng \"Vết thương linh hồn\" trên tất cả địch sẽ nhận 50 điểm Năng lượng chìa khóa bạc, mỗi lần loại bỏ một tầng \"Sợ hãi cố định\" trên tất cả địch khiến tất cả thức tỉnh thể khác nhận 2 điểm Aliemus."
  },
  AwakerTalent_79211_TalentName_1 = {
