  AwakerTalent_83778_TalentDesc_1 = {
    Text = "· Kepersant bản thân, bánh xe định mệnh và giao ước trang bị cung cấp mỗi 1% kháng cự cái chết, tăng sát thương cơ bản 0,2%, khiên tăng 0,05%."
  },
  AwakerTalent_83778_TalentName_1 = {
    Text = "Diễn tàn"
  },
  AwakerTalent_84132_TalentDesc_1 = {
    Text = "·Mỗi khi Aurita có 1 cấp hồi phục điên cuồng, khi trận chiến bắt đầu nhận được thiệt hại xúc tu bằng 2% tấn công của Aurita, mỗi 1% tỷ lệ chí mạng, khi trận chiến bắt đầu nhận được thiệt hại xúc tu bằng 1% tấn công của Aurita."
  },
  AwakerTalent_84132_TalentName_1 = {
    Text = "Chú tiên vui vẻ"
  },
  AwakerTalent_89775_TalentDesc_1 = {
    Text = "·Mỗi khi đánh ra lần đầu \"Lông đen\" trong lượt, gây \"Xói mòn\" bằng 840% tấn công của bản thân lên tất cả kẻ thù và nhận 10 điểm điên cuồng.\n·Mỗi 1% khuếch đại sát thương mà Cas-tơ-lơ có sẽ làm tăng 1% \"Xói mòn\" cơ bản được áp dụng.\n·Sau khi trận chiến kết thúc, \"Xói mòn\" mà Cas-tơ-lơ áp dụng trong cuộc khám phá này sẽ tăng vĩnh viễn 20%.\n·\"Xói mòn\"áp dụng trong trận chiến lãnh đạo sẽ được nhân đôi.\n·Sau khi Cas-tơ-lơ áp dụng \"Xói mòn\", sát thương của bản thân trong lượt này sẽ tăng 5% theo lượng áp dụng.\n·Sát thương mà Cas-tơ-lơ gây ra sẽ không làm mất \"Xói mòn\"."
  },
  AwakerTalent_89775_TalentName_1 = {
    Text = "Lông Thánh Tẩy Tội"
  },
  AwakerTalent_95804_TalentDesc_1 = {
    Text = "·Dulecai sẽ nhận được 1 \"mảnh vỡ\" sau khi tiêu diệt kẻ thù hoặc sử dụng cú bùng nổ điên cuồng để gây sát thương cho trùm.\n·Tối đa tích lũy 3 \"mảnh vỡ\".\n·\"Mảnh vỡ\" sẽ được kế thừa đến trận đấu tiếp theo."
  },
